CustomField.formula:
IF(fxCurrentMonthStartDate__c < Resource_User_Record__r.StartDate__c && Resource_User_Record__r.StartDate__c < fxCurrentMonthEndDate__c,
(5*(FLOOR((fxLatestWorkDay__c - DATE(1900,1,8))/7 )) + MIN(5,MOD(fxLatestWorkDay__c - DATE(1900,1,8),7))) - (5*(FLOOR((Resource_User_Record__r.StartDate__c - DATE(1900,1,8))/7)) + MIN(5,MOD(Resource_User_Record__r.StartDate__c - DATE(1900,1,8),7)))+1 ,
/*calculates # business days if Resource starts during month*/
(5*(FLOOR((fxLatestWorkDay__c - DATE(1900,1,8))/7 )) + MIN(5,MOD(fxLatestWorkDay__c - DATE(1900,1,8),7))) - (5*(FLOOR((fxCurrentMonthStartDate__c - DATE(1900,1,8))/7)) + MIN(5,MOD(fxCurrentMonthStartDate__c - DATE(1900,1,8),7)))+1)
/*calculates standard # business days during month*/
